package com.mustafafaraz.locateme

import android.os.Bundle
import android.view.View
import android.widget.ArrayAdapter
import android.widget.Button
import android.widget.EditText
import android.widget.ImageView
import android.widget.Spinner
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import androidx.core.content.ContextCompat

class ReportItem : AppCompatActivity() {

    private lateinit var toggleLost: TextView
    private lateinit var toggleFound: TextView
    private lateinit var locationLabel: TextView
    private lateinit var reportButton: Button

    private lateinit var itemTitle: EditText
    private lateinit var itemCategory: Spinner
    private lateinit var itemDescription: EditText
    private lateinit var itemLocation: Spinner
    private lateinit var contactMethod: EditText
    private lateinit var contactInfo: EditText

    private var isLostItem = true

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_report_item)

        initializeViews()
        setupToggleListeners()
        setupSpinners()
        setupClickListeners()
    }

    private fun initializeViews() {
        toggleLost = findViewById(R.id.toggle_lost)
        toggleFound = findViewById(R.id.toggle_found)
        locationLabel = findViewById(R.id.location_label)
        reportButton = findViewById(R.id.report_button)

        itemTitle = findViewById(R.id.item_title)
        itemCategory = findViewById(R.id.item_category)
        itemDescription = findViewById(R.id.item_description)
        itemLocation = findViewById(R.id.item_location)
        contactMethod = findViewById(R.id.contact_method)
        contactInfo = findViewById(R.id.contact_info)
    }

    private fun setupToggleListeners() {
        toggleLost.setOnClickListener {
            if (!isLostItem) {
                switchToLost()
            }
        }

        toggleFound.setOnClickListener {
            if (isLostItem) {
                switchToFound()
            }
        }
    }

    private fun setupSpinners() {
        // Category Spinner
        val categories = arrayOf(
            "Select Category",
            "Electronics",
            "Bags",
            "Keys",
            "Clothing",
            "Books",
            "Accessories",
            "Other"
        )
        val categoryAdapter = ArrayAdapter(this, android.R.layout.simple_spinner_item, categories)
        categoryAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
        itemCategory.adapter = categoryAdapter

        // Location Spinner
        val locations = arrayOf(
            "Select Location",
            "Library - 1st floor",
            "Library - 2nd floor",
            "Library - 3rd floor",
            "Cafeteria",
            "Main Building",
            "Lab Block",
            "Sports Complex",
            "Parking Area",
            "Other"
        )
        val locationAdapter = ArrayAdapter(this, android.R.layout.simple_spinner_item, locations)
        locationAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
        itemLocation.adapter = locationAdapter
    }

    private fun setupClickListeners() {
        // Back button
        findViewById<ImageView>(R.id.back_button).setOnClickListener {
            finish()
        }

        // Report button
        reportButton.setOnClickListener {
            handleReportSubmit()
        }

        // Add photo button
        findViewById<View>(R.id.add_photo_button).setOnClickListener {
            // TODO: Implement photo picker
        }

        // Bottom navigation
        findViewById<View>(R.id.nav_search).setOnClickListener {
            // TODO: Navigate to search/home
        }

        findViewById<View>(R.id.nav_report).setOnClickListener {
            // Already on report screen
        }

        findViewById<View>(R.id.nav_profile).setOnClickListener {
            // TODO: Navigate to profile
        }
    }

    private fun switchToLost() {
        isLostItem = true

        // Update toggle buttons
        toggleLost.setBackgroundResource(R.drawable.selected_button_login_signup)
        toggleLost.setTextColor(ContextCompat.getColor(this, R.color.black))

        toggleFound.background = null
        toggleFound.setTextColor(ContextCompat.getColor(this, R.color.black))

        // Update text labels
        locationLabel.text = "Where did you lose it? *"
        reportButton.text = "Report Lost Item"
    }

    private fun switchToFound() {
        isLostItem = false

        // Update toggle buttons
        toggleLost.background = null
        toggleLost.setTextColor(ContextCompat.getColor(this, R.color.black))

        toggleFound.setBackgroundResource(R.drawable.selected_button_login_signup)
        toggleFound.setTextColor(ContextCompat.getColor(this, R.color.black))

        // Update text labels
        locationLabel.text = "Where did you find it? *"
        reportButton.text = "Report Found Item"
    }

    private fun handleReportSubmit() {
        val title = itemTitle.text.toString()
        val category = itemCategory.selectedItem.toString()
        val description = itemDescription.text.toString()
        val location = itemLocation.selectedItem.toString()
        val method = contactMethod.text.toString()
        val contact = contactInfo.text.toString()

        // Validation
        if (title.isEmpty()) {
            itemTitle.error = "Please enter item title"
            return
        }

        if (category == "Select Category") {
            // Show error for category
            return
        }

        if (description.isEmpty()) {
            itemDescription.error = "Please enter description"
            return
        }

        if (location == "Select Location") {
            // Show error for location
            return
        }

        if (method.isEmpty()) {
            contactMethod.error = "Please enter contact method"
            return
        }

        if (contact.isEmpty()) {
            contactInfo.error = "Please enter contact information"
            return
        }

        // TODO: Submit the report to backend/database
        val itemType = if (isLostItem) "Lost" else "Found"

        // For now, just finish the activity
        finish()
    }
}

package com.mustafafaraz.locateme

import android.app.AlertDialog
import android.content.Intent
import android.os.Bundle
import android.util.Log
import android.widget.Button
import android.widget.EditText
import android.widget.ImageView
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import com.mustafafaraz.locateme.data.api.RetrofitClient
import com.mustafafaraz.locateme.data.model.ChangePasswordRequest
import com.mustafafaraz.locateme.utils.TokenManager
import kotlinx.coroutines.launch

class Settings : AppCompatActivity() {

    private lateinit var backButton: ImageView
    private lateinit var currentPassword: EditText
    private lateinit var newPassword: EditText
    private lateinit var confirmPassword: EditText
    private lateinit var changePasswordButton: Button
    private lateinit var deleteAccountButton: Button

    private lateinit var tokenManager: TokenManager

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_settings)

        tokenManager = TokenManager(this)

        initializeViews()
        setupClickListeners()
    }

    private fun initializeViews() {
        backButton = findViewById(R.id.back_button)
        currentPassword = findViewById(R.id.current_password)
        newPassword = findViewById(R.id.new_password)
        confirmPassword = findViewById(R.id.confirm_password)
        changePasswordButton = findViewById(R.id.change_password_button)
        deleteAccountButton = findViewById(R.id.delete_account_button)
    }

    private fun setupClickListeners() {
        backButton.setOnClickListener {
            finish()
        }

        changePasswordButton.setOnClickListener {
            handleChangePassword()
        }

        deleteAccountButton.setOnClickListener {
            showDeleteAccountConfirmation()
        }
    }

    private fun handleChangePassword() {
        val current = currentPassword.text.toString().trim()
        val new = newPassword.text.toString().trim()
        val confirm = confirmPassword.text.toString().trim()

        // Validation
        if (current.isEmpty()) {
            currentPassword.error = "Current password is required"
            currentPassword.requestFocus()
            return
        }

        if (new.isEmpty()) {
            newPassword.error = "New password is required"
            newPassword.requestFocus()
            return
        }

        if (new.length < 6) {
            newPassword.error = "Password must be at least 6 characters"
            newPassword.requestFocus()
            return
        }

        if (confirm.isEmpty()) {
            confirmPassword.error = "Please confirm your password"
            confirmPassword.requestFocus()
            return
        }

        if (new != confirm) {
            confirmPassword.error = "Passwords do not match"
            confirmPassword.requestFocus()
            return
        }

        lifecycleScope.launch {
            try {
                changePasswordButton.isEnabled = false
                changePasswordButton.text = "Changing..."

                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) {
                    Toast.makeText(this@Settings, "Please login", Toast.LENGTH_SHORT).show()
                    finish()
                    return@launch
                }

                val authHeader = "Bearer $token"
                val request = ChangePasswordRequest(
                    currentPassword = current,
                    newPassword = new
                )

                val response = RetrofitClient.apiService.changePassword(authHeader, request)

                changePasswordButton.isEnabled = true
                changePasswordButton.text = "Change Password"

                if (response.isSuccessful && response.body()?.success == true) {
                    Toast.makeText(this@Settings, "Password changed successfully", Toast.LENGTH_SHORT).show()

                    // Clear password fields
                    currentPassword.text?.clear()
                    newPassword.text?.clear()
                    confirmPassword.text?.clear()
                } else {
                    val errorMsg = response.body()?.message ?: "Failed to change password"
                    Toast.makeText(this@Settings, errorMsg, Toast.LENGTH_SHORT).show()
                    Log.e("Settings", "Error: ${response.code()} - ${response.errorBody()?.string()}")
                }
            } catch (e: Exception) {
                changePasswordButton.isEnabled = true
                changePasswordButton.text = "Change Password"
                Log.e("Settings", "Error changing password", e)
                Toast.makeText(this@Settings, "Network error: ${e.message}", Toast.LENGTH_SHORT).show()
            }
        }
    }

    private fun showDeleteAccountConfirmation() {
        AlertDialog.Builder(this)
            .setTitle("Delete Account")
            .setMessage("Are you absolutely sure you want to delete your account? This action cannot be undone. All your items and data will be permanently deleted.")
            .setPositiveButton("Delete") { _, _ ->
                handleDeleteAccount()
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun handleDeleteAccount() {
        lifecycleScope.launch {
            try {
                deleteAccountButton.isEnabled = false
                deleteAccountButton.text = "Deleting..."

                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) {
                    Toast.makeText(this@Settings, "Please login", Toast.LENGTH_SHORT).show()
                    finish()
                    return@launch
                }

                val authHeader = "Bearer $token"
                val response = RetrofitClient.apiService.deleteAccount(authHeader)

                deleteAccountButton.isEnabled = true
                deleteAccountButton.text = "Delete Account"

                if (response.isSuccessful && response.body()?.success == true) {
                    Toast.makeText(this@Settings, "Account deleted successfully", Toast.LENGTH_LONG).show()

                    // Clear session data
                    tokenManager.clearAllData()

                    // Redirect to login page
                    val intent = Intent(this@Settings, LoginSignup::class.java)
                    intent.flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
                    startActivity(intent)
                    finish()
                } else {
                    Toast.makeText(this@Settings, "Failed to delete account", Toast.LENGTH_SHORT).show()
                    Log.e("Settings", "Error: ${response.code()} - ${response.message()}")
                }
            } catch (e: Exception) {
                deleteAccountButton.isEnabled = true
                deleteAccountButton.text = "Delete Account"
                Log.e("Settings", "Error deleting account", e)
                Toast.makeText(this@Settings, "Network error: ${e.message}", Toast.LENGTH_SHORT).show()
            }
        }
    }
}

package com.mustafafaraz.locateme.data.api

import com.mustafafaraz.locateme.data.model.*
import retrofit2.Response
import retrofit2.http.*

interface ApiService {

    // Authentication Endpoints
    @POST("api/auth/signup")
    suspend fun signup(@Body request: SignupRequest): Response<ApiResponse<AuthResponse>>

    @POST("api/auth/login")
    suspend fun login(@Body request: LoginRequest): Response<ApiResponse<AuthResponse>>

    // User Profile Endpoints
    @GET("api/users/profile")
    suspend fun getProfile(
        @Header("Authorization") token: String
    ): Response<ApiResponse<User>>

    @PUT("api/users/profile")
    suspend fun updateProfile(
        @Header("Authorization") token: String,
        @Body request: UpdateProfileRequest
    ): Response<ApiResponse<User>>

    // Item Endpoints
    @POST("api/items")
    suspend fun createItem(
        @Header("Authorization") token: String,
        @Body request: CreateItemRequest
    ): Response<ApiResponse<Item>>

    @GET("api/items")
    suspend fun getItems(
        @Header("Authorization") token: String,
        @Query("type") type: String? = null,
        @Query("category") category: String? = null,
        @Query("search") search: String? = null
    ): Response<ApiResponse<List<Item>>>

    @GET("api/items/{id}")
    suspend fun getItemById(
        @Header("Authorization") token: String,
        @Path("id") itemId: Int
    ): Response<ApiResponse<Item>>

    @GET("api/items/my-items")
    suspend fun getMyItems(
        @Header("Authorization") token: String,
        @Query("type") type: String? = null,
        @Query("status") status: String? = null
    ): Response<ApiResponse<List<Item>>>

    @PUT("api/items/{id}")
    suspend fun updateItem(
        @Header("Authorization") token: String,
        @Path("id") itemId: Int,
        @Body request: UpdateItemRequest
    ): Response<ApiResponse<Item>>

    @DELETE("api/items/{id}")
    suspend fun deleteItem(
        @Header("Authorization") token: String,
        @Path("id") itemId: Int
    ): Response<ApiResponse<Unit>>
}

package com.mustafafaraz.locateme.data.api

import com.mustafafaraz.locateme.data.model.*
import retrofit2.Response
import retrofit2.http.*

interface ApiService {

    // Authentication Endpoints
    @POST("api/auth/signup")
    suspend fun signup(@Body request: SignupRequest): Response<ApiResponse<AuthResponse>>

    @POST("api/auth/login")
    suspend fun login(@Body request: LoginRequest): Response<ApiResponse<AuthResponse>>

    // User Profile Endpoints
    @GET("api/users/profile")
    suspend fun getProfile(
        @Header("Authorization") token: String
    ): Response<ApiResponse<User>>

    @PUT("api/users/profile")
    suspend fun updateProfile(
        @Header("Authorization") token: String,
        @Body request: UpdateProfileRequest
    ): Response<ApiResponse<User>>

    @PUT("api/users/change-password")
    suspend fun changePassword(
        @Header("Authorization") token: String,
        @Body request: ChangePasswordRequest
    ): Response<ApiResponse<Unit>>

    @DELETE("api/users/account")
    suspend fun deleteAccount(
        @Header("Authorization") token: String
    ): Response<ApiResponse<Unit>>

    // Item Endpoints
    @POST("api/items")
    suspend fun createItem(
        @Header("Authorization") token: String,
        @Body request: CreateItemRequest
    ): Response<ApiResponse<Item>>

    @GET("api/items")
    suspend fun getItems(
        @Header("Authorization") token: String,
        @Query("type") type: String? = null,
        @Query("category") category: String? = null,
        @Query("search") search: String? = null
    ): Response<ApiResponse<List<Item>>>

    @GET("api/items/{id}")
    suspend fun getItemById(
        @Header("Authorization") token: String,
        @Path("id") itemId: Int
    ): Response<ApiResponse<Item>>

    @GET("api/items/my-items")
    suspend fun getMyItems(
        @Header("Authorization") token: String,
        @Query("type") type: String? = null,
        @Query("status") status: String? = null
    ): Response<ApiResponse<List<Item>>>

    @PUT("api/items/{id}")
    suspend fun updateItem(
        @Header("Authorization") token: String,
        @Path("id") itemId: Int,
        @Body request: UpdateItemRequest
    ): Response<ApiResponse<Item>>

    @DELETE("api/items/{id}")
    suspend fun deleteItem(
        @Header("Authorization") token: String,
        @Path("id") itemId: Int
    ): Response<ApiResponse<Unit>>
}

package com.mustafafaraz.locateme.data.model

import com.google.gson.annotations.SerializedName

data class User(
    val id: Int,
    @SerializedName("full_name")
    val fullName: String,
    val email: String,
    @SerializedName("student_id")
    val studentId: String,
    val batch: String,
    val department: String,
    val section: String,
    @SerializedName("profile_pic")
    private val _profilePic: String? = null,
    @SerializedName("created_at")
    val createdAt: String? = null,
    val stats: UserStats? = null
) {
    // Remove :5000 port from profile pic URL
    val profilePic: String?
        get() = _profilePic?.replace(":5000", "")
}

data class UserStats(
    @SerializedName("total_items")
    val totalItems: Int,
    @SerializedName("resolved_items")
    val resolvedItems: Int,
    @SerializedName("success_rate")
    val successRate: Float
)

data class UpdateProfileRequest(
    val fullName: String,
    val studentId: String,
    val batch: String,
    val department: String,
    val section: String,
    val profilePic: String? = null // base64 encoded image (optional, only if changed)
)

